-- Only inside BEGIN ... ROLLBACK; independent real-schema rehearsal, no messages.
CREATE TEMP TABLE pos_purchase_proof(name text PRIMARY KEY,passed boolean DEFAULT true);
CREATE FUNCTION pg_temp.pos_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'POS purchase check failed: %',label;END IF;INSERT INTO pos_purchase_proof(name) VALUES(label);END$$;
CREATE FUNCTION pg_temp.pos_body(sh uuid,supplier uuid,item uuid,warehouse uuid,account uuid,unit_name text,paid numeric DEFAULT 115) RETURNS jsonb LANGUAGE sql AS $$
 SELECT jsonb_build_object('shiftId',sh,'expectedTotal',115,'newSupplier',NULL,'newItems','[]'::jsonb,'attachmentIds','[]'::jsonb,'invoice',jsonb_build_object(
 'id',gen_random_uuid(),'revision',0,'kind','invoice','title','POS shared purchase rollback','number','','date',(now() AT TIME ZONE 'Asia/Riyadh')::date,'dueDate',NULL,'supplierId',supplier,'supplierIds','[]'::jsonb,'warehouseId',warehouse,'sourceId',NULL,'currency','SAR','exchangeRate',1,'taxInclusive',false,'discount',0,'discountType','amount','shipping',0,'adjustment',0,'adjustmentAccountId',NULL,'paid',paid,'accountId',account,'received',true,'note','POS shared purchase rollback','terms','','customValues','{}'::jsonb,'customStatus','','lines',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'itemId',item,'description','POS shared purchase rollback item','unit',unit_name,'quantity',1,'price',100,'discount',0,'discountType','amount','taxRate',15,'costCenterId',NULL))))
$$;
CREATE FUNCTION pg_temp.pos_denied(c uuid,body jsonb,label text,request uuid DEFAULT gen_random_uuid()) RETURNS void LANGUAGE plpgsql AS $$DECLARE denied boolean:=false;BEGIN BEGIN PERFORM public.brand_finance_execute(c,'shift_purchase',body,request);EXCEPTION WHEN OTHERS THEN denied:=true;END;PERFORM pg_temp.pos_assert(denied,label);END$$;
CREATE FUNCTION pg_temp.pos_flags(c uuid,owner_id uuid,item_allowed boolean,supplier_allowed boolean,credit_allowed boolean) RETURNS void LANGUAGE plpgsql AS $$
DECLARE prior text:=current_setting('request.jwt.claim.sub',true);cfg jsonb;BEGIN
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);
 cfg:=erp_purchase_private.settings(c)||jsonb_build_object('cashierCreateItem',item_allowed,'cashierCreateSupplier',supplier_allowed,'cashierCreditPurchase',credit_allowed);
 PERFORM public.erp_purchases_write(c,'settings',cfg,gen_random_uuid());
 PERFORM set_config('request.jwt.claim.sub',coalesce(prior,''),true);
END$$;
DO $test$
DECLARE c uuid;owner_id uuid;staff uuid;outsider uuid;warehouse uuid;drawer uuid;other_account uuid;fixture_unit_id uuid;unit_name text;shift uuid:=gen_random_uuid();
 item uuid:=gen_random_uuid();new_item uuid:=gen_random_uuid();supplier uuid:=gen_random_uuid();new_supplier uuid:=gen_random_uuid();funding uuid:=gen_random_uuid();
 body jsonb;original_body jsonb;credit_body jsonb;new_supplier_body jsonb;new_item_body jsonb;result jsonb;catalog jsonb;settings jsonb;created_supplier jsonb;legacy jsonb;legacy_request uuid:=gen_random_uuid();legacy_doc uuid;
 doc uuid;credit_doc uuid;request uuid:=gen_random_uuid();before_cash numeric;before_qty numeric;before_count bigint;denied boolean;foreign_item uuid;foreign_warehouse uuid;history_ids uuid[];history_hash text;branch_a uuid:=gen_random_uuid();branch_b uuid:=gen_random_uuid();branch_item uuid:=gen_random_uuid();employee uuid:=gen_random_uuid();branch_body jsonb;
BEGIN
 SELECT id,owner_user_id INTO STRICT c,owner_id FROM public.cafes WHERE slug='test-cafe' AND deleted_at IS NULL;
 SELECT p.id INTO STRICT staff FROM public.profiles p WHERE p.status='active' AND p.role='customer' AND p.id<>owner_id AND NOT EXISTS(SELECT 1 FROM public.bf_staff s WHERE s.cafe_id=c AND s.user_id=p.id) ORDER BY p.id LIMIT 1;
 SELECT p.id INTO STRICT outsider FROM public.profiles p WHERE p.status='active' AND p.role='customer' AND p.id NOT IN(owner_id,staff) AND NOT EXISTS(SELECT 1 FROM public.bf_staff s WHERE s.cafe_id=c AND s.user_id=p.id) ORDER BY p.id LIMIT 1;
 SELECT id INTO STRICT warehouse FROM public.bf_warehouses WHERE cafe_id=c AND active ORDER BY id LIMIT 1;
 SELECT id INTO STRICT drawer FROM public.bf_accounts WHERE cafe_id=c AND active AND kind='cash' AND is_cashier_drawer AND NOT coalesce(frozen,false) AND deleted_at IS NULL ORDER BY id LIMIT 1;
 SELECT id INTO STRICT other_account FROM public.bf_accounts WHERE cafe_id=c AND active AND kind='bank' AND deleted_at IS NULL ORDER BY id LIMIT 1;
 SELECT id,name INTO STRICT fixture_unit_id,unit_name FROM public.bf_item_units WHERE cafe_id=c ORDER BY id LIMIT 1;
 SELECT array_agg(id),md5(coalesce(jsonb_agg(to_jsonb(d) ORDER BY id)::text,'')) INTO history_ids,history_hash FROM public.bf_documents d WHERE cafe_id=c;
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);
 INSERT INTO public.bf_staff(cafe_id,user_id,name,role) VALUES(c,staff,'POS shared purchase rollback cashier','cashier');
 UPDATE public.bf_shifts SET status='closed',closed_at=now() WHERE cafe_id=c AND status IN('open','handover');
 INSERT INTO public.bf_shifts(id,cafe_id,user_id,account_id,opening_cash,expected_cash) VALUES(shift,c,staff,drawer,0,0);
 INSERT INTO public.bf_items(id,cafe_id,name,sku,unit,unit_id,active) VALUES(item,c,'POS shared purchase rollback item','POS-SHARED-'||item,unit_name,fixture_unit_id,true);
 INSERT INTO public.bf_parties(id,cafe_id,name,kind,active) VALUES(supplier,c,'POS shared purchase rollback supplier','supplier',true);
 INSERT INTO public.bf_documents(id,cafe_id,kind,total,created_by,note) VALUES(funding,c,'journal',0,owner_id,'POS shared purchase rollback funding');
 PERFORM brand_finance_private.line(c,funding,drawer,10000,0);
 PERFORM brand_finance_private.line(c,funding,brand_finance_private.account(c,'3000'),0,10000);
 UPDATE public.bf_settings SET closed_through=NULL WHERE cafe_id=c;
 PERFORM pg_temp.pos_flags(c,owner_id,false,true,false);
 PERFORM set_config('request.jwt.claim.sub',staff::text,true);
 catalog:=public.brand_finance_pos_purchase_catalog(c,shift);
 PERFORM pg_temp.pos_assert(catalog->'permissions'='{"createItem":false,"createSupplier":true,"credit":false}'::jsonb,'cashier receives default owner-controlled capabilities');
 PERFORM pg_temp.pos_assert(catalog ?& ARRAY['settings','suppliers','units','itemDefaults','costCenters','blockedItems','categories'] AND NOT(catalog ?| ARRAY['records','invoices','payments','statements']),'catalog is shared form data without broad financial history');
 SELECT coalesce(sum(debit-credit),0) INTO before_cash FROM public.bf_journal WHERE cafe_id=c AND account_id=drawer;
 body:=pg_temp.pos_body(shift,supplier,item,warehouse,drawer,unit_name);original_body:=body;
 result:=public.brand_finance_execute(c,'shift_purchase',body,request);doc:=(result->>'id')::uuid;
 PERFORM pg_temp.pos_assert(EXISTS(SELECT 1 FROM public.bf_documents WHERE id=doc AND cafe_id=c AND kind='purchase' AND created_by=staff AND shift_id=shift AND account_id=drawer AND total=115 AND tax=15 AND paid=115),'cashier purchase posts original ledger with own shift drawer and tax');
 PERFORM pg_temp.pos_assert(EXISTS(SELECT 1 FROM public.erp_purchase_documents WHERE cafe_id=c AND finance_id=doc AND status='posted'),'shared ERP purchase record linked to original financial invoice');
 PERFORM pg_temp.pos_assert((SELECT quantity FROM public.bf_stock WHERE cafe_id=c AND warehouse_id=warehouse AND item_id=item)=1 AND (SELECT coalesce(sum(debit-credit),0) FROM public.bf_journal WHERE cafe_id=c AND account_id=drawer)=before_cash-115,'shared purchase receives stock and spends exact drawer balance');
 PERFORM pg_temp.pos_assert(public.brand_finance_execute(c,'shift_purchase',body,request)->>'id'=doc::text AND (SELECT quantity FROM public.bf_stock WHERE cafe_id=c AND warehouse_id=warehouse AND item_id=item)=1,'same request retries without duplicate invoice or stock');
 PERFORM pg_temp.pos_denied(c,jsonb_set(body,'{invoice,note}','"Changed"'), 'changed request payload rejected',request);
 PERFORM pg_temp.pos_denied(c,pg_temp.pos_body(shift,supplier,item,warehouse,drawer,unit_name,0),'credit denied by default');
 PERFORM pg_temp.pos_denied(c,jsonb_set(pg_temp.pos_body(shift,supplier,item,warehouse,drawer,unit_name),'{invoice,accountId}',to_jsonb(other_account)),'arbitrary payment account injection denied');
 PERFORM pg_temp.pos_denied(c,jsonb_set(pg_temp.pos_body(shift,supplier,item,warehouse,drawer,unit_name),'{expectedTotal}','116'),'stale expected total rejected');
 PERFORM pg_temp.pos_denied(c,jsonb_set(pg_temp.pos_body(shift,supplier,item,warehouse,drawer,unit_name),'{attachmentIds}',jsonb_build_array(gen_random_uuid())),'foreign or missing attachment rejected');
 denied:=false;BEGIN PERFORM public.erp_purchases_write(c,'save',body->'invoice',gen_random_uuid());EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;PERFORM pg_temp.pos_assert(denied,'cashier cannot bypass shift entry through general ERP purchase writer');
 denied:=false;BEGIN PERFORM public.brand_finance_execute(c,'item',jsonb_build_object('name','Forbidden item','unitId',fixture_unit_id),gen_random_uuid());EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;PERFORM pg_temp.pos_assert(denied,'cashier general inventory privilege not elevated');
 created_supplier:=jsonb_build_object('id',new_supplier,'revision',0,'name','POS shared purchase rollback new supplier','phone','','email','','taxNumber','','active',true,'firstName','','lastName','','mobile','','commercialRegistration','','number','','currency','SAR','address',jsonb_build_object('building','','street','','additional','','district','','city','','postal','','short','','country','SA'),'contacts','[]'::jsonb,'addresses','[]'::jsonb,'note','','openingBalance',0,'openingDate',(now() AT TIME ZONE 'Asia/Riyadh')::date);
 new_supplier_body:=pg_temp.pos_body(shift,new_supplier,item,warehouse,drawer,unit_name)||jsonb_build_object('newSupplier',created_supplier);
 PERFORM pg_temp.pos_flags(c,owner_id,false,false,false);
 PERFORM pg_temp.pos_denied(c,new_supplier_body,'owner disabling supplier creation enforced by SQL');
 PERFORM pg_temp.pos_assert(NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE id=new_supplier),'denied supplier remains uncreated');
 PERFORM pg_temp.pos_flags(c,owner_id,false,true,false);
 PERFORM pg_temp.pos_denied(c,jsonb_set(new_supplier_body,'{newSupplier,openingBalance}','100'),'new supplier cannot inject financial opening balance');
 result:=public.brand_finance_execute(c,'shift_purchase',new_supplier_body,gen_random_uuid());
 PERFORM pg_temp.pos_assert(EXISTS(SELECT 1 FROM public.erp_purchase_suppliers WHERE cafe_id=c AND id=new_supplier) AND EXISTS(SELECT 1 FROM public.bf_documents WHERE id=(result->>'id')::uuid AND party_id=new_supplier),'allowed supplier creates original supplier profile and purchase atomically');
 new_item_body:=pg_temp.pos_body(shift,supplier,new_item,warehouse,drawer,unit_name)||jsonb_build_object('newItems',jsonb_build_array(jsonb_build_object('id',new_item,'name','POS shared purchase rollback new item','sku','POS-SHARED-'||new_item,'unitId',fixture_unit_id,'barcode','')));
 PERFORM pg_temp.pos_denied(c,new_item_body,'owner disabling new item enforced by SQL');
 PERFORM pg_temp.pos_assert(NOT EXISTS(SELECT 1 FROM public.bf_items WHERE id=new_item),'denied item remains uncreated');
 PERFORM pg_temp.pos_flags(c,owner_id,true,true,true);
 result:=public.brand_finance_execute(c,'shift_purchase',new_item_body,gen_random_uuid());
 PERFORM pg_temp.pos_assert(EXISTS(SELECT 1 FROM public.bf_items WHERE cafe_id=c AND id=new_item AND unit_id=fixture_unit_id) AND (SELECT quantity FROM public.bf_stock WHERE cafe_id=c AND item_id=new_item AND warehouse_id=warehouse)=1,'allowed new item receives stock through original inventory');
 credit_body:=pg_temp.pos_body(shift,supplier,item,warehouse,drawer,unit_name,0);
 SELECT coalesce(sum(debit-credit),0) INTO before_cash FROM public.bf_journal WHERE cafe_id=c AND account_id=drawer;
 result:=public.brand_finance_execute(c,'shift_purchase',credit_body,gen_random_uuid());credit_doc:=(result->>'id')::uuid;
 PERFORM pg_temp.pos_assert(EXISTS(SELECT 1 FROM public.bf_documents WHERE id=credit_doc AND paid=0 AND total=115 AND shift_id=shift) AND (brand_finance_private.document_state(c,credit_doc)->>'outstanding')::numeric=115,'allowed credit creates original supplier payable');
 PERFORM pg_temp.pos_assert((SELECT coalesce(sum(debit-credit),0) FROM public.bf_journal WHERE cafe_id=c AND account_id=drawer)=before_cash,'credit never spends drawer cash');
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);
 PERFORM public.erp_purchases_write(c,'supplier',created_supplier||'{"revision":1,"openingBalance":-30}'::jsonb,gen_random_uuid());
 PERFORM set_config('request.jwt.claim.sub',staff::text,true);
 result:=public.brand_finance_execute(c,'shift_purchase',pg_temp.pos_body(shift,new_supplier,item,warehouse,drawer,unit_name,0),gen_random_uuid());
 PERFORM pg_temp.pos_assert((brand_finance_private.document_state(c,(result->>'id')::uuid)->>'outstanding')::numeric=115 AND EXISTS(SELECT 1 FROM public.erp_purchase_credits WHERE cafe_id=c AND supplier_id=new_supplier AND amount=30 AND used=0),'cashier credit permission does not spend supplier advances');
 PERFORM pg_temp.pos_assert(NOT EXISTS(SELECT 1 FROM public.bf_documents WHERE reference_id=(result->>'id')::uuid AND kind='settlement'),'cashier purchase does not create unauthorized automatic settlement');
 body:=jsonb_set(jsonb_set(jsonb_set(pg_temp.pos_body(shift,supplier,item,warehouse,drawer,unit_name),'{invoice,currency}','"USD"'),'{invoice,exchangeRate}','3.75'),'{expectedTotal}','431.25');
 result:=public.brand_finance_execute(c,'shift_purchase',body,gen_random_uuid());
 PERFORM pg_temp.pos_assert(EXISTS(SELECT 1 FROM public.bf_documents WHERE id=(result->>'id')::uuid AND total=431.25 AND paid=431.25 AND tax=56.25),'foreign currency amount and paid converted once to SAR by original core');
 INSERT INTO public.bf_staff(cafe_id,user_id,name,role) VALUES(c,outsider,'POS shared purchase rollback manager','manager');
 PERFORM set_config('request.jwt.claim.sub',outsider::text,true);
 PERFORM pg_temp.pos_flags(c,owner_id,false,false,false);
 catalog:=jsonb_build_object('permissions',erp_purchase_private.pos_permissions(c));
 PERFORM pg_temp.pos_assert(catalog->'permissions'='{"createItem":true,"createSupplier":false,"credit":false}'::jsonb,'manager retains item creation while supplier and credit follow owner switches');
 denied:=false;BEGIN PERFORM public.erp_purchases_write(c,'settings',erp_purchase_private.settings(c)||'{"cashierCreditPurchase":true}'::jsonb,gen_random_uuid());EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;PERFORM pg_temp.pos_assert(denied,'manager cannot elevate owner-controlled purchase permissions');
 DELETE FROM public.bf_staff WHERE cafe_id=c AND user_id=outsider;
 PERFORM set_config('request.jwt.claim.sub',staff::text,true);
 UPDATE public.bf_parties SET phone='0500000011' WHERE id=supplier;
 legacy:=jsonb_build_object('shiftId',shift,'supplierName','POS shared purchase rollback supplier','supplierPhone','0500000011','warehouseId',warehouse,'vatRate',15,'taxInclusive',false,'expectedTotal',115,'note','POS shared purchase rollback legacy','lines',jsonb_build_array(jsonb_build_object('itemId',item,'quantity',1,'unitPrice',100)));
 PERFORM pg_temp.pos_flags(c,owner_id,false,false,false);
 result:=public.brand_finance_execute(c,'shift_purchase',legacy,legacy_request);legacy_doc:=(result->>'id')::uuid;
 PERFORM pg_temp.pos_assert(EXISTS(SELECT 1 FROM public.bf_documents WHERE id=legacy_doc AND party_id=supplier AND paid=115 AND shift_id=shift),'deployed legacy cashier still purchases with existing supplier when creation disabled');
 PERFORM pg_temp.pos_denied(c,jsonb_set(legacy,'{supplierName}','"POS shared purchase rollback legacy new"'),'legacy implicit new supplier denied by owner policy');
 UPDATE public.bf_parties SET active=false WHERE id=supplier;
 PERFORM pg_temp.pos_assert(public.brand_finance_execute(c,'shift_purchase',legacy,legacy_request)->>'id'=legacy_doc::text,'legacy completed retry survives policy revocation and deactivated supplier');
 UPDATE public.bf_parties SET active=true WHERE id=supplier;
 PERFORM pg_temp.pos_flags(c,owner_id,false,true,false);
 result:=public.brand_finance_execute(c,'shift_purchase',jsonb_set(legacy,'{supplierName}','"POS shared purchase rollback legacy new"'),gen_random_uuid());
 PERFORM pg_temp.pos_assert(EXISTS(SELECT 1 FROM public.bf_documents d JOIN public.bf_parties s ON s.id=d.party_id WHERE d.id=(result->>'id')::uuid AND s.name='POS shared purchase rollback legacy new'),'legacy implicit supplier remains allowed when owner enables it');
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);
 PERFORM pg_temp.pos_denied(c,pg_temp.pos_body(shift,supplier,item,warehouse,drawer,unit_name),'owner cannot spend another cashier shift');
 PERFORM pg_temp.pos_denied(c,original_body,'request actor isolation preserved',request);
 PERFORM set_config('request.jwt.claim.sub',outsider::text,true);
 PERFORM pg_temp.pos_denied(c,pg_temp.pos_body(shift,supplier,item,warehouse,drawer,unit_name),'unrelated tenant actor cannot purchase');
 PERFORM set_config('request.jwt.claim.sub',staff::text,true);
 SELECT id INTO foreign_item FROM public.bf_items WHERE cafe_id<>c AND active LIMIT 1;
 IF foreign_item IS NOT NULL THEN PERFORM pg_temp.pos_denied(c,pg_temp.pos_body(shift,supplier,foreign_item,warehouse,drawer,unit_name),'foreign tenant item rejected');END IF;
 SELECT id INTO foreign_warehouse FROM public.bf_warehouses WHERE cafe_id<>c AND active LIMIT 1;
 IF foreign_warehouse IS NOT NULL THEN PERFORM pg_temp.pos_denied(c,pg_temp.pos_body(shift,supplier,item,foreign_warehouse,drawer,unit_name),'foreign tenant warehouse rejected');END IF;
 INSERT INTO public.branches(id,cafe_id,name) VALUES(branch_a,c,'POS shared purchase rollback branch A'),(branch_b,c,'POS shared purchase rollback branch B');
 denied:=false;BEGIN PERFORM public.brand_finance_pos_purchase_catalog(c,shift);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;PERFORM pg_temp.pos_assert(denied,'cashier with unassigned branch cannot bypass ERP branch authorization');
 INSERT INTO public.erp_hr_employees(id,cafe_id,code,first_name,user_id,payload,branch_id) VALUES(employee,c,'POS-SHARED-TEST','POS shared purchase rollback',staff,'{}',branch_a);
 INSERT INTO public.erp_branch_scopes(cafe_id,user_id,branch_id) VALUES(c,staff,branch_a);
 INSERT INTO public.erp_branch_settings(cafe_id,payload) VALUES(c,'{"shareProducts":false,"shareSuppliers":false,"specifyAccounts":true}') ON CONFLICT(cafe_id) DO UPDATE SET payload=excluded.payload;
 INSERT INTO public.bf_items(id,cafe_id,name,sku,unit,unit_id) VALUES(branch_item,c,'POS shared purchase rollback other branch','POS-BRANCH-'||branch_item,unit_name,fixture_unit_id);
 INSERT INTO public.erp_inventory_items(cafe_id,item_id,payload) VALUES(c,branch_item,'{"buyPrice":999,"note":"other branch private"}');
 INSERT INTO public.erp_branch_resources(cafe_id,kind,record_id,branch_id) VALUES(c,'item',item,branch_a),(c,'item',branch_item,branch_b),(c,'account',drawer,branch_a),(c,'supplier',supplier,branch_a);
 catalog:=public.brand_finance_pos_purchase_catalog(c,shift);
 PERFORM pg_temp.pos_assert(catalog->'branchScope'->>'branchId'=branch_a::text,'purchase catalog returns verified active branch scope');
 PERFORM pg_temp.pos_assert(NOT(catalog->'itemDefaults'?branch_item::text),'purchase catalog excludes other branch item price metadata');
 branch_body:=pg_temp.pos_body(shift,supplier,item,warehouse,drawer,unit_name)||jsonb_build_object('branchScope',catalog->'branchScope');
 PERFORM pg_temp.pos_denied(c,branch_body-'branchScope','branch scope revision required for new shared posting');
 result:=public.brand_finance_execute(c,'shift_purchase',branch_body,gen_random_uuid());
 PERFORM pg_temp.pos_assert(EXISTS(SELECT 1 FROM public.erp_branch_documents WHERE cafe_id=c AND document_id=(result->>'id')::uuid AND branch_id=branch_a),'shared purchase captures original financial branch identity');
 PERFORM pg_temp.pos_denied(c,pg_temp.pos_body(shift,supplier,branch_item,warehouse,drawer,unit_name)||jsonb_build_object('branchScope',catalog->'branchScope'),'same tenant other branch item rejected');
 PERFORM set_config('erp.branch_cafe','',true);PERFORM set_config('erp.branch_id','',true);
 UPDATE public.bf_shifts SET supervisor_paused=true WHERE id=shift;
 PERFORM pg_temp.pos_denied(c,pg_temp.pos_body(shift,supplier,item,warehouse,drawer,unit_name),'paused shift rejected');
 UPDATE public.bf_shifts SET supervisor_paused=false,status='closed',closed_at=now() WHERE id=shift;
 PERFORM pg_temp.pos_denied(c,pg_temp.pos_body(shift,supplier,item,warehouse,drawer,unit_name),'closed shift rejected');
 PERFORM pg_temp.pos_assert(public.brand_finance_execute(c,'shift_purchase',original_body,request)->>'id'=doc::text,'completed retry remains safe after shift closes');
 PERFORM pg_temp.pos_assert(NOT EXISTS(SELECT document_id FROM public.bf_journal WHERE cafe_id=c GROUP BY document_id HAVING sum(debit-credit)<>0),'all original journals balanced');
 PERFORM pg_temp.pos_assert((SELECT md5(coalesce(jsonb_agg(to_jsonb(d) ORDER BY id)::text,'')) FROM public.bf_documents d WHERE id=ANY(history_ids))=history_hash,'all preexisting financial documents unchanged');
 PERFORM pg_temp.pos_assert(NOT has_function_privilege('anon','public.brand_finance_pos_purchase_catalog(uuid,uuid)','EXECUTE') AND has_function_privilege('authenticated','public.brand_finance_pos_purchase_catalog(uuid,uuid)','EXECUTE'),'catalog grants scoped to authenticated');
 PERFORM pg_temp.pos_assert(NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN unnest(ARRAY['anon','authenticated','service_role']) role_name WHERE n.nspname='erp_purchase_private' AND p.proname IN('pos_post','pos_save','pos_supplier','pos_execute','pos_assert','pos_cash') AND has_function_privilege(role_name,p.oid,'EXECUTE')),'private financial clones cannot be invoked directly by application roles');
 SET CONSTRAINTS ALL IMMEDIATE;
END $test$;
SELECT count(*) checks,jsonb_agg(jsonb_build_object('name',name,'passed',passed) ORDER BY name) evidence FROM pos_purchase_proof;
